-- Klangradar-Stadtkatalog-Import: Wien.
-- Quelle: kuratierte Recherche (Stand 26.08.2026), siehe docs/12-city-expansion-import.md
-- für Herkunft/Konventionen. is_verified bleibt false (redaktionelle Freigabe
-- aussteht), Koordinaten wurden per OpenStreetMap/Nominatim aus der Adresse
-- geokodiert (ungeprüfte Drittquelle, wie schon beim ursprünglichen München-Import
-- in 20260817000002_import_excel_stammdaten.sql).
--
-- Upsert-Reihenfolge: Venues zuerst (Ensembles referenzieren sie über
-- home_venue_slug), dann Personen (global, upsert über slug -- kann bereits
-- existierende Personen aus anderen Städten/München aktualisieren), dann
-- Ensembles, zuletzt Aliase. ON CONFLICT DO UPDATE überschreibt is_verified
-- NICHT auf false, falls eine Zeile bereits redaktionell freigegeben war.

-- Reconciliation: Slug-Angleichung an bereits produktiv angelegte Venues
-- der parallelen Codex-Session (20261031000010/012/013/014), siehe
-- gleiche Begründung in 20261029000004_city_import_berlin.sql.

-- Reconciliation: vier Wiener Chöre/Klangkörper entfernt (Wiener
-- Singverein, Wiener Sängervereinigung, Wiener Concert-Verein, Wiener
-- Männergesang-Verein) -- alle scheitern am geteilten Trigger
-- guard_ensemble_name_quality (Institutions-Wort 'verein' im Namen ohne
-- erkanntes Ensemble-Marker-Wort). Reale, bekannte Klangkörper, aber
-- ohne den geteilten Validierungs-Trigger anzufassen hier nicht
-- importierbar -- spätere Nacharbeit: entweder Trigger-Regex erweitern
-- oder gezielt per Admin-Formular (umgeht den Trigger) nachtragen.
-- 'wiener-staatsoper' und 'volksoper-wien' brauchen keine Angleichung --
-- exakt gleicher Slug dort bereits, "on conflict" unten greift direkt.
update venues set slug = 'musikverein-wien-grosser-saal' where slug = 'wiener-musikverein' and not exists (select 1 from venues v2 where v2.slug = 'musikverein-wien-grosser-saal');
update venues set slug = 'wiener-konzerthaus-grosser-saal' where slug = 'wiener-konzerthaus' and not exists (select 1 from venues v2 where v2.slug = 'wiener-konzerthaus-grosser-saal');
update venues set slug = 'musiktheater-an-der-wien' where slug = 'theater-an-der-wien' and not exists (select 1 from venues v2 where v2.slug = 'musiktheater-an-der-wien');
update venues set slug = 'orf-radiokulturhaus-grosser-sendesaal' where slug = 'orf-radiokulturhaus' and not exists (select 1 from venues v2 where v2.slug = 'orf-radiokulturhaus-grosser-sendesaal');

